with with_windows as (select id, promo_code, ends_on, discount_pct, round(discount_pct / sum(discount_pct) over (partition by promo_code), 4) as discount_pct_share, first_value(channel, true) over (partition by channel order by ends_on asc, id asc rows between unbounded preceding and current row) as first_known_channel, percent_rank() over (order by discount_pct desc) as discount_pct_percent_rank, dense_rank() over (partition by channel order by discount_pct desc) as discount_pct_dense_rank from promotions where promo_code in ('SPRING10', 'BUNDLE', 'WELCOME5')) select id, promo_code, ends_on, first_known_channel, discount_pct_percent_rank from with_windows order by promo_code desc nulls first;
